window.__votdWeek && window.__votdWeek({"week":"2029-08-27","reading":"Doctrine and Covenants 93","days":[{"d":"2029-08-27","ref":"D&C 93:1","b":"D&C","c":93,"v":1,"he":"אָמֵן כֹּה אָמַר יְהוָה וְהָיָה כִּי כׇל־נֶפֶשׁ הָעֹזֶבֶת חַטֹּאתֶיהָ וּבָאָה אֵלַי וְקֹרֵאת בִּשְׁמִי וְשֹׁמַעַת בְּקוֹלִי וְשֹׁמֶרֶת מִצְוֹתַי תִּרְאֶה פָנַי וְתֵדַע כִּי אֲנִי הוּא׃","en":"Verily, thus saith the Lord: It shall come to pass that every soul who forsaketh his sins and cometh unto me, and calleth on my name, and obeyeth my voice, and keepeth my commandments, shall see my face and know that I am;"},{"d":"2029-08-28","ref":"D&C 93:19","b":"D&C","c":93,"v":19,"he":"אֲנִי נֹתֵן לָכֶם אֶת־הַדְּבָרִים הָאֵלֶּה לְמַעַן תָּבִינוּ וְתֵדְעוּ אֵיךְ לְהִשְׁתַּחֲווֹת וְתֵדְעוּ אֶת־אֲשֶׁר לוֹ אַתֶּם מִשְׁתַּחֲוִים לְמַעַן תָּבֹאוּ אֶל־הָאָב בִּשְׁמִי וּבְעִתּוֹ תְּקַבְּלוּ מִמְּלֹאוֹ׃","en":"I give unto you these sayings that you may understand and know how to worship, and know what you worship, that you may come unto the Father in my name, and in due time receive of his fulness."},{"d":"2029-08-29","ref":"D&C 93:33","b":"D&C","c":93,"v":33,"he":"כִּי הָאָדָם רוּחַ הוּא הַיְסֹדוֹת הֵם נִצְחִיִּים וְרוּחַ וִיסוֹד מְחֻבָּרִים יַחַד לֹא יִפָּרְדוּ מְקַבְּלִים מְלֹא שִׂמְחָה׃","en":"For man is spirit. The elements are eternal, and spirit and element, inseparably connected, receive a fulness of joy;"},{"d":"2029-08-30","ref":"D&C 93:35","b":"D&C","c":93,"v":35,"he":"הַיְסֹדוֹת מִשְׁכַּן אֱלֹהִים הֵם אָכֵן הָאָדָם מִשְׁכַּן אֱלֹהִים הוּא גַּם הֵיכָלוֹת וְכׇל־הֵיכׇל הַמְחֻלָּל יַשְׁמִידֶנּוּ אֱלֹהִים׃","en":"The elements are the tabernacle of God; yea, man is the tabernacle of God, even temples; and whatsoever temple is defiled, God shall destroy that temple."},{"d":"2029-08-31","ref":"D&C 93:38","b":"D&C","c":93,"v":38,"he":"כׇּל־רוּחַ אָדָם הָיְתָה נְקִיָּה בָּרֵאשִׁית וֵאלֹהִים גָּאַל אֶת־הָאָדָם מִן־הַמַּפָּלָה בְּנֵי אָדָם חָזְרוּ לִהְיוֹת בִּימֵי יַנְקוּתָם נְקִיִּים לִפְנֵי אֱלֹהִים׃","en":"Every spirit of man was innocent in the beginning; and God having redeemed man from the fall, men became again, in their infant state, innocent before God."},{"d":"2029-09-01","ref":"D&C 93:39","b":"D&C","c":93,"v":39,"he":"וְהָרָשָׁע הַהוּא בָּא וְלֹקֵחַ אוֹר וֶאֱמֶת בְּמֶרִי מִבְּנֵי אָדָם וּבִגְלַל מָסֹרֶת אֲבוֹתֵיהֶם׃","en":"And that wicked one cometh and taketh away light and truth, through disobedience, from the children of men, and because of the tradition of their fathers."},{"d":"2029-09-02","ref":"D&C 93:53","b":"D&C","c":93,"v":53,"he":"וְאָמֵן אֲנִי אֹמֵר לָכֶם רְצוֹנִי אֲשֶׁר־תְּמַהֲרוּ לְתַרְגֵּם אֶת־כְּתוּבַי וּלְהַשִּׂיג דַּעַת תּוֹלְדוֹת וּמְדִינוֹת וּמַמְלָכוֹת וְחֻקֵּי אֱלֹהִים וְאָדָם וְכׇל־זֹאת לִישׁוּעַת צִיּוֹן אָמֵן׃","en":"And, verily I say unto you, that it is my will that you should hasten to translate my scriptures, and to obtain a knowledge of history, and of countries, and of kingdoms, of laws of God and man, and all this for the salvation of Zion. Amen."}]});
